<?php
[, $monthEnd]=pay_month($month);
$q=$pdo->prepare("SELECT e.user_id,u.name,e.employee_code FROM employees e JOIN users u ON u.id=e.user_id WHERE e.deleted_at IS NULL AND e.employment_status='Active' AND u.active=1 AND (e.joining_date IS NULL OR e.joining_date<=?) ORDER BY u.name");$q->execute([$monthEnd]);$eligible=$q->fetchAll(PDO::FETCH_ASSOC);$total=count($eligible);$salaryReady=0;$missing=[];
$q=$pdo->prepare('SELECT COUNT(*) FROM hr_salary_assignments WHERE employee_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?)');
foreach($eligible as $e){$q->execute([$e['user_id'],$monthEnd,$month.'-01']);if($q->fetchColumn())$salaryReady++;else $missing[]=$e;}
$sum=['gross'=>0,'lop'=>0,'deductions'=>0,'net'=>0];$generated=0;$exceptions=0;
foreach($rows as $r){foreach(['gross','deductions','net'] as $key)$sum[$key]+=(int)$r[$key];$s=json_decode($r['snapshot'],true)?:[];$sum['lop']+=(int)($s['lop']??0);$generated+=(int)(pay_simple_stage($r)!=='Draft');$exceptions+=(int)($r['exceptions']!=='');}
$currency=$run?(json_decode($run['settings_snapshot'],true)['payroll']['currency']??'INR'):'INR';
?>
<div class="pay-heading"><div><span class="eyebrow">MONTHLY OVERVIEW</span><h2><?=h(date('F Y',strtotime($month.'-01')))?></h2><p>Salary, attendance and payslips in one place.</p></div><form method="get" class="pay-inline"><input type="hidden" name="page" value="payroll_dashboard"><label>Payroll month<input type="month" name="month" value="<?=h($month)?>" required></label><button class="button">View month</button></form></div>
<div class="pay-metrics"><?php foreach(['Employees'=>[$total,'Active by month end'],'Gross Payroll'=>[$currency.' '.pay_amount($sum['gross']),'Saved payroll calculation'],'Attendance Deduction'=>[$currency.' '.pay_amount($sum['lop']),'Unpaid attendance only'],'Total Deductions'=>[$currency.' '.pay_amount($sum['deductions']),'Attendance + other deductions'],'Net Payroll'=>[$currency.' '.pay_amount($sum['net']),'After deductions'],'Payslips Generated'=>[$generated.' / '.$total,'Draft and finalized copies']] as $label=>[$value,$hint]):?><article class="card pay-metric"><span><?=h($label)?></span><strong><?=h((string)$value)?></strong><small><?=h($hint)?></small></article><?php endforeach;?></div>
<div class="pay-dashboard-columns"><section class="card"><div class="pay-heading"><h2>Payroll status</h2><a class="button primary" href="?page=payroll_payslips&amp;month=<?=h($month)?>">Open payslips</a></div>
<?php $readiness=['Salary configured'=>[$salaryReady,$total], 'Attendance checked'=>[$run?count($rows)-$exceptions:0,$total], 'Payroll calculated'=>[$run&&$run['status']!=='Draft'?count($rows):0,$total], 'Payslips generated'=>[$generated,$total]];foreach($readiness as $label=>[$value,$max]):?><div class="pay-progress-row"><div><strong><?=h($label)?></strong><span><?=$value?> / <?=$max?></span></div><progress max="<?=max(1,$max)?>" value="<?=$value?>"></progress></div><?php endforeach;?><p class="pay-muted">Attendance readiness is confirmed during calculation. Unresolved punches or missing schedules need review.</p></section>
<section class="card"><h2>Action required</h2><a class="pay-action-row" href="?page=payroll_payslips&amp;month=<?=h($month)?>&amp;attention=salary"><strong><?=count($missing)?></strong><span>Employees missing salary</span><span>→</span></a><a class="pay-action-row" href="?page=payroll_payslips&amp;month=<?=h($month)?>&amp;attention=exceptions"><strong><?=$exceptions?></strong><span>Payroll exceptions to resolve</span><span>→</span></a><a class="pay-action-row" href="?page=payroll_payslips&amp;month=<?=h($month)?>&amp;status=Draft"><strong><?=max(0,$total-$generated)?></strong><span>Payslips not generated</span><span>→</span></a></section></div>
<section class="card"><h2>Recent activity</h2><div class="pay-activity"><?php $activity=$pdo->query("SELECT a.action,a.created_at,u.name FROM hr_audit a JOIN users u ON u.id=a.actor_id WHERE a.action LIKE 'payroll.%' ORDER BY a.id DESC LIMIT 8")->fetchAll(PDO::FETCH_ASSOC);foreach($activity as $a):?><div><span class="pay-activity-dot"></span><p><strong><?=h(ucwords(str_replace('.',' ',substr($a['action'],8))))?></strong><small><?=h($a['name'].' · '.$a['created_at'])?></small></p></div><?php endforeach;if(!$activity):?><p class="pay-muted">Salary changes and payslip actions will appear here.</p><?php endif;?></div></section>
